require __DIR__.'/config.php';$u=imam_only();$imamId=request_imam_id();$date=queryv('tanggal',date('Y-m-d'));if(!valid_date($date))$date=date('Y-m-d');$month=substr($date,0,7);$monthReq=queryv('bulan','');if(valid_month($monthReq)&&$monthReq!==$month){$month=$monthReq;$date=$month.'-01';}
$q=db()->prepare("SELECT s.*,i.name imam_name FROM schedules s JOIN imams i ON i.id=s.imam_id WHERE s.prayer_date=? ORDER BY FIELD(s.prayer,'Subuh','Dzuhur','Ashar','Maghrib','Isya')");$q->execute([$date]);$rows=$q->fetchAll();
$pageTitle='Jadwal masjid';$active='jadwal';require __DIR__.'/partials/mobile_header.php';
?><h1>Jadwal masjid</h1><p class="caption">Kota: Jakarta · WIB</p><h3 class="mt24 text-green"><?=h(pretty_date($date))?></h3><form method="get" class="phone-card soft mt16"><label>Pilih tanggal di kalender<input type="date" name="tanggal" value="<?=h($date)?>" onchange="this.form.submit()"></label></form><div class="flex mb12"><a class="btn light small" href="<?=h(link_to('imam_jadwal.php',['tanggal'=>date('Y-m-d',strtotime($date.' -1 day'))]))?>">‹ Hari lalu</a><a class="btn light small" href="<?=h(link_to('imam_jadwal.php',['tanggal'=>date('Y-m-d',strtotime($date.' +1 day'))]))?>">Hari berikut ›</a></div>
<?php foreach($rows as $s):?><div class="phone-card"><div class="phone-row"><strong><?=h($s['prayer'])?> · <?=h(substr($s['start_time'],0,5))?> WIB</strong><?=pill((int)$s['imam_id']===$imamId?status_confirmation($s['confirmation']):'Imam lain')?></div><div class="caption mt8"><?=h($s['imam_name'])?></div><div class="tiny muted mt8"><?=(int)$s['imam_id']===$imamId?'Penugasan Anda':'Jadwal imam lain'?></div><?php if((int)$s['imam_id']===$imamId):?><div class="mt8"><a class="phone-cta" href="<?=h(link_to('imam_konfirmasi.php',['id'=>$s['id']]))?>"><?= $s['confirmation']==='pending'?'Konfirmasi kesediaan':'Ubah jawaban' ?></a></div><?php endif;?></div><?php endforeach;?><?php if(!$rows):?><div class="phone-card empty">Belum ada jadwal yang terbit untuk tanggal ini.</div><?php endif;?><p class="help">Waktu sholat merupakan jam penugasan yang dicatat pengurus, bukan otomatisasi jadwal adzan resmi.</p>
